nta.declaration:
clock global;

// We assume TIMERS are given higher priority than other nodes
// A High priority is executed first

int measure_now = false;



// Constants for identifying monitored packets
const int EMPTY = 0;
const int MONITORS = 20; 
const int FIRST_PAYLOAD = 1;
const int MAX_PAYLOAD = 20;
const int BUF_SIZE = 2;
int PAYLOAD = FIRST_PAYLOAD;
int LAST_PAYLOAD = EMPTY;
int LAST_GENERATOR = 0;  // Safe default; always set by monitored DataGenerator before use

const int POLICY_DROP_NEWEST = 0;
const int POLICY_DROP_OLDEST = 1;
const int POLICY_DROP_FAIR_SOURCE = 2;
const int POLICY_DROP_LOWEST_PRIO = 3;

const int SOURCE_UNKNOWN = -1;

int dropped_packets = 0;

!!!DECLARATIONS!!!
// Some general stuff
const int MONITOR_FREE = 0;
const int MONITOR_SENT = 1;

int nm=0; // Next monitor
int lm=0; // Last monitor
int pd; // Published data
int ps; // Published source

int free_monitors = MONITORS;
int monitor_payload[MONITORS];
int monitor_deadline[MONITORS];
broadcast chan new_job, start_monitor, publish[C];

bool deadline_missed = false;


// *queued* jobs 
int QUEUES[C][BUF_SIZE];
int QUEUES_COUNT[C];

// This should all be initialized to SOURCE_UNKNOWN
int QUEUE_SRC[C][BUF_SIZE];


int SRC_IN_QUEUE[C];

// *scheduled* jobs
int HOST_JOBS[C][3]; // ID, data, source
int HOST_JOBS_COUNT;


bool waiting_jobs() {
    int i;
    for (i=0; i<C; i++) {
        if (QUEUES_COUNT[i] > 0) return true;
    }
    return false;
}


//// QUEUE FUNCTIONS

void queue_append(int task, int data, int src) {
    int pos = QUEUES_COUNT[task];
    
    assert(src != SOURCE_UNKNOWN);  // Check before modifying state

    QUEUES[task][pos] = data;
    QUEUE_SRC[task][pos] = src;
    QUEUES_COUNT[task] += 1;
    SRC_IN_QUEUE[src] += 1;
}

void queue_remove(int task, int pos) {
    int i;
    int rem_src = QUEUE_SRC[task][pos];
    assert(rem_src != SOURCE_UNKNOWN);
    assert(SRC_IN_QUEUE[rem_src] > 0);
    SRC_IN_QUEUE[rem_src] -= 1;

	for (i=pos; i<BUF_SIZE-1; i++) {
        QUEUES[task][i] = QUEUES[task][i+1];
        QUEUE_SRC[task][i] = QUEUE_SRC[task][i+1];
    }

    QUEUES[task][BUF_SIZE-1] = EMPTY;
    QUEUE_SRC[task][BUF_SIZE-1] = SOURCE_UNKNOWN;

    QUEUES_COUNT[task] -= 1;
}

int fair_source_victim(int task) {
    int i;
	int s;
	int c;
    int best_idx = 0;
    int best_count = -1;

    for (i=0; i<QUEUES_COUNT[task]; i++) {
		s = QUEUE_SRC[task][i];
        assert(s != SOURCE_UNKNOWN); 
		c = SRC_IN_QUEUE[s];

        if (c > best_count) {
            best_count = c;
            best_idx = i;
        }
    }

    return best_idx;
}

int lowest_prio_victim(int task) {
    int i;
	int s;
	int p;
    int best_idx = 0;
    int worst_prio = -99999;

    for (i=0; i<QUEUES_COUNT[task]; i++) {
		s =  QUEUE_SRC[task][i];
        assert(s != SOURCE_UNKNOWN);
		p = PRIO[s];

        if (p > worst_prio) {
            worst_prio = p;
            best_idx = i;
        }
    }

    return best_idx;
}    



void queue_job(int task, int data, int src) {
	int victim;
	int victim_src;
	int victim_prio;
	int incoming_prio;

	// Source must never be unknown - fail fast if it is
	assert(src != SOURCE_UNKNOWN);

    if (QUEUES_COUNT[task] < BUF_SIZE) {
        queue_append(task, data, src);
        return;
    } 

    dropped_packets += 1;
        
    if (QUEUE_POLICY == POLICY_DROP_NEWEST) {
        // Silently drop
        return;
    }
    
    if (QUEUE_POLICY == POLICY_DROP_OLDEST) {
        queue_remove(task, 0);
        queue_append(task, data, src);
		return;
    }

    if (QUEUE_POLICY == POLICY_DROP_FAIR_SOURCE) {
		victim = fair_source_victim(task);
        queue_remove(task, victim);
        queue_append(task, data, src);
        return;
    }

    if (QUEUE_POLICY == POLICY_DROP_LOWEST_PRIO) {
		victim = lowest_prio_victim(task);
		victim_src = QUEUE_SRC[task][victim];
        assert(victim_src != SOURCE_UNKNOWN);
        
		victim_prio = PRIO[victim_src];
        assert(src != SOURCE_UNKNOWN);
		incoming_prio = PRIO[src];

        if (incoming_prio < victim_prio) {
            queue_remove(task, victim);
            queue_append(task, data, src);
        }
    
        // if not we drop
        return;
	}
    assert(false);
}


// Right-most job first, i.e., greatest priority first
void schedule() {
    int i, j, tmp_id, tmp_data, tmp_src;

    // Bubble sort by priority, swapping all three fields
    for (i=0; i<HOST_JOBS_COUNT; i++) {
        for (j=0; j<HOST_JOBS_COUNT-1; j++) {
            if (PRIO[HOST_JOBS[j][0]] > PRIO[HOST_JOBS[j+1][0]]) {
                tmp_id = HOST_JOBS[j][0];
                tmp_data = HOST_JOBS[j][1];
                tmp_src = HOST_JOBS[j][2];
                HOST_JOBS[j][0] = HOST_JOBS[j+1][0];
                HOST_JOBS[j][1] = HOST_JOBS[j+1][1];
                HOST_JOBS[j][2] = HOST_JOBS[j+1][2];
                HOST_JOBS[j+1][0] = tmp_id;
                HOST_JOBS[j+1][1] = tmp_data;
                HOST_JOBS[j+1][2] = tmp_src;
            }        
        }
    }
}

int dequeue(int task) {
    int tmp;
    assert(QUEUES_COUNT[task] > 0);
    tmp = QUEUES[task][0];
    queue_remove(task, 0);
    return tmp;
}

void take_jobs() {
	int i, j, s;

    assert(HOST_JOBS_COUNT == 0);   // Host jobs should be zero here
    for (i=0; i<C; i++) {
        if (QUEUES_COUNT[i] > 0) {
			s = QUEUE_SRC[i][0];
            j = dequeue(i);
            HOST_JOBS[HOST_JOBS_COUNT][0] = i;
            HOST_JOBS[HOST_JOBS_COUNT][1] = j;
			HOST_JOBS[HOST_JOBS_COUNT][2] = s;
            HOST_JOBS_COUNT += 1;
        }
    }
    schedule();
}

int next_job_idx() {
    HOST_JOBS_COUNT--;
    return HOST_JOBS_COUNT;
}

// If value is negative, read from local memory DATA[-value].
int get_data(int value) {
	if (value >= 0) {
		return value;
	}

	return DATA[-value];
}

// If value is negative, read from local source memory for node -value.
int get_source(int value) {
	if (value >= 0) {
		return value;
	}

	return SRC[-value];
}

void assign_monitor() {
    assert(free_monitors > 0);
    monitor_payload[nm] = PAYLOAD;
    monitor_deadline[nm] = DEADLINES[LAST_GENERATOR];
    free_monitors -= 1;
  
    PAYLOAD = PAYLOAD + 1;

    nm = (nm + 1) % MONITORS;
}


// True if payload is monitored (i.e., not empty or already seen)
bool relevant_payload(int payload) {
    int i = 0;
    if (payload == EMPTY)
        return false;
    for (i = 0; i < MONITORS; i++) {
        if (monitor_payload[i] == payload)
            return true;
    }

    return false;
}




// When freeing up, we free up all monitors incl. those whose data got thrown away.
void release_monitors() {
    int i;
    int count = 0;  // Safeguard against infinite loops
    // We could get an old value, in that case it is not in the monitored payloads
    bool old_value = true;
    for (i = 0; i < MONITORS; i++) {
        if (monitor_payload[i] == pd)
            old_value = false;
    }

    // If it is an old value, we can just ignore it as it has already been seen once
    if (old_value)
    	return;

    // Free previously used monitors (with safeguard against infinite loops)
    while (monitor_payload[lm] != pd && count < MONITORS) {
        monitor_payload[lm] = EMPTY;
        free_monitors += 1;
        lm = (lm + 1) % MONITORS;
        count += 1;
    }
    
    // Also free the one just handled.
    LAST_PAYLOAD = monitor_payload[lm];
    monitor_payload[lm] = EMPTY;
    free_monitors += 1;
    lm = (lm + 1) % MONITORS;
}

template.declaration:
clock x;
int idx;
int job;
int data;
int src;

nta.system:
// These are always used

host = Host(deterministic_host);


!!!SYSTEM!!!
